import express from 'express';
import multer from 'multer';
import path from 'path';
import fs from 'fs';

const app = express();

// Create avatars directory if it doesn't exist
const avatarDir = path.join(process.cwd(), 'uploads', 'avatars');
if (!fs.existsSync(avatarDir)) {
  fs.mkdirSync(avatarDir, { recursive: true });
}

// Configure multer
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, avatarDir);
  },
  filename: (req, file, cb) => {
    const userId = req.user.id; // Assumes authenticated user
    const ext = path.extname(file.originalname);
    cb(null, `${userId}-avatar${ext}`);
  }
});

const fileFilter = (req, file, cb) => {
  const allowedMimes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
  if (allowedMimes.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(new Error('Only image files are allowed'), false);
  }
};

const upload = multer({
  storage,
  fileFilter,
  limits: { fileSize: 5 * 1024 * 1024 } // 5MB
});

// Upload endpoint
app.post('/api/avatar', upload.single('avatar'), (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  res.json({
    success: true,
    filename: req.file.filename,
    path: `/avatars/${req.file.filename}`
  });
});

// Error handling middleware for multer
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    if (err.code === 'FILE_TOO_LARGE') {
      return res.status(400).json({ error: 'File too large (max 5MB)' });
    }
    return res.status(400).json({ error: 'File upload failed' });
  }
  if (err) {
    return res.status(400).json({ error: err.message });
  }
  next();
});

app.listen(3000, () => console.log('Server running on port 3000'));
```

**Key points:**
- **multer** handles multipart form data; `upload.single('avatar')` expects a field named `avatar`
- **diskStorage** saves files to `uploads/avatars/` with userId-based naming (prevents overwrites)
- **fileFilter** validates image MIME types; rejects non-images
- **fileSize limit** capped at 5MB; adjust as needed
- **Error middleware** catches multer errors (file too large, missing file, etc.)

**Client usage:**
```javascript
const formData = new FormData();
formData.append('avatar', fileInput.files[0]);
fetch('/api/avatar', { method: 'POST', body: formData });
```

